<script setup>
import { computed } from 'vue'
import PInputText from 'primevue/inputtext'
import PSelect from 'primevue/select'
const props = defineProps({ draft: { type: Object, required: true }, item: { type: Object, required: true }, disabled: Boolean })
const types = [{ label: '직접 증익', value: 'NET_PROFIT' }, { label: '추가 매출', value: 'REVENUE' }]
const categories = [{ label: '운영 개선', value: 'OPERATIONS' }, { label: '구매·외주', value: 'PROCUREMENT' }, { label: '매출 확대', value: 'REVENUE' }, { label: '인력 관련', value: 'HEADCOUNT' }, { label: 'R&D', value: 'RND' }, { label: '미분류', value: 'UNKNOWN' }]
/** 요청의 고정 기준 이후에 반영 가능한 월을 만든다.
 * Args: 없음. Returns: 월 선택지. Raises: 없음. Side Effects: 없음.
 */
function months() { const options = []; for (let month = props.item.baseMonth + 1; month <= 12; month++) options.push({ label: `${props.item.year}년 ${month}월`, value: month }); return options }
const monthOptions = computed(months)
</script>
<template><div class="reply-candidate-fields"><div class="field wide"><label :for="`reply-title-${item.id}`">검토한 과제명</label><PInputText :id="`reply-title-${item.id}`" v-model="draft.title" maxlength="200" :disabled="disabled" /></div><div class="field"><label :for="`reply-type-${item.id}`">효과 유형</label><PSelect :input-id="`reply-type-${item.id}`" v-model="draft.type" :options="types" option-label="label" option-value="value" :disabled="disabled" /></div><div class="field"><label :for="`reply-amount-${item.id}`">{{ draft.type === 'REVENUE' ? '추가 매출' : '비용 차감 전 직접 증익' }} · 억 원</label><PInputText :id="`reply-amount-${item.id}`" v-model="draft.amountEok" inputmode="decimal" maxlength="40" placeholder="확인한 효과 금액" :disabled="disabled" /></div><div v-if="draft.type === 'REVENUE'" class="field"><label :for="`reply-margin-${item.id}`">공헌이익률 · %</label><PInputText :id="`reply-margin-${item.id}`" v-model="draft.contributionMarginPercent" inputmode="decimal" maxlength="10" placeholder="0~100" :disabled="disabled" /></div><div class="field"><label :for="`reply-cost-${item.id}`">실행 부대비용 · 억 원</label><PInputText :id="`reply-cost-${item.id}`" v-model="draft.implementationCostEok" inputmode="decimal" maxlength="40" :disabled="disabled" /></div><div class="field"><label :for="`reply-embedded-${item.id}`">기존 전망 반영분 · 억 원</label><PInputText :id="`reply-embedded-${item.id}`" v-model="draft.embeddedEffectEok" inputmode="decimal" maxlength="40" :disabled="disabled" /></div><div class="field"><label :for="`reply-month-${item.id}`">효과 반영 월</label><PSelect :input-id="`reply-month-${item.id}`" v-model="draft.recognitionMonth" :options="monthOptions" option-label="label" option-value="value" placeholder="잔여 월 선택" :disabled="disabled" /></div><div class="field"><label :for="`reply-category-${item.id}`">효과 분류</label><PSelect :input-id="`reply-category-${item.id}`" v-model="draft.category" :options="categories" option-label="label" option-value="value" :disabled="disabled" /></div><div class="field"><label :for="`reply-duplicate-${item.id}`">중복 효과 묶음 · 선택</label><PInputText :id="`reply-duplicate-${item.id}`" v-model="draft.duplicateGroup" maxlength="100" placeholder="동일 효과의 공통 식별자" :disabled="disabled" /></div><p class="wide">{{ draft.type === 'REVENUE' ? '추가 매출 × 공헌이익률' : '직접 증익' }} − 실행 부대비용 − 기존 전망 반영분으로 계산합니다. 비용·반영분이 0인지도 확인해 주세요.</p></div></template>
